'use strict';

// Endpoint 策略：HTTPS baseURL 白名单与结果下载策略。
// 禁止信任上游任意重定向、任意结果主机或非 HTTPS 结果地址。

function policyError(code, message) {
  const error = new Error(message);
  error.code = code;
  error.status = 400;
  return error;
}

function normalizedHost(value) {
  return String(value || '').trim().toLowerCase().replace(/^\[|\]$/g, '');
}

// baseURL 必须是 HTTPS，且可选通过白名单限制主机。
function assertBaseUrl(baseURL, allowedHosts = null) {
  let url;
  try {
    url = new URL(baseURL);
  } catch (_) {
    throw policyError('ENDPOINT_BASE_URL_INVALID', 'baseURL 无效');
  }
  if (url.protocol !== 'https:') {
    throw policyError('ENDPOINT_BASE_URL_HTTPS_REQUIRED', 'baseURL 必须是 HTTPS');
  }
  if (url.username || url.password) {
    throw policyError('ENDPOINT_BASE_URL_INVALID', 'baseURL 不得含用户名或密码');
  }
  if (allowedHosts && Array.isArray(allowedHosts) && allowedHosts.length > 0) {
    const host = normalizedHost(url.hostname);
    if (!allowedHosts.map(h => normalizedHost(h)).includes(host)) {
      throw policyError('ENDPOINT_BASE_URL_NOT_ALLOWED', 'baseURL 不在允许白名单');
    }
  }
  return url;
}

// 结果 URL 必须 HTTPS；禁止重定向；可选限制结果主机。
function assertResultUrl(resultUrl, allowedHosts = null) {
  let url;
  try {
    url = new URL(resultUrl);
  } catch (_) {
    throw policyError('RESULT_URL_INVALID', '结果地址无效');
  }
  if (url.protocol !== 'https:') {
    throw policyError('RESULT_URL_HTTPS_REQUIRED', '结果地址必须是 HTTPS');
  }
  if (url.username || url.password) {
    throw policyError('RESULT_URL_INVALID', '结果地址不得含用户名或密码');
  }
  if (allowedHosts && Array.isArray(allowedHosts) && allowedHosts.length > 0) {
    const host = normalizedHost(url.hostname);
    if (!allowedHosts.map(h => normalizedHost(h)).includes(host)) {
      throw policyError('RESULT_URL_NOT_ALLOWED', '结果地址不在允许白名单');
    }
  }
  return url;
}

module.exports = { assertBaseUrl, assertResultUrl, normalizedHost };
